// The whole client SDK a user gets, compared: for each description of `sdk-compare/cases.mjs`,
// an SDK generated by flowapi (`config draft`, then `generate`) and by each other generator that
// writes a TypeScript client and runs with Node alone (`run.mjs sdk`), each measured the same way
// (`sdk-compare/build.mjs`: generation as a fresh process, the median of `--rounds`, its peak
// memory, what it wrote, `tsc --strict` errors), then each called through its own surface
// (`sdk-compare/adapters.mjs`) against one mock server made from the description
// (`sdk-compare/mock.mjs`), and what reached the server held to what the specification asks
// (`sdk-compare/behavior.mjs`). Writes results/sdk-compare.json and results/sdk-compare.md.
//
//     node bench/competitors/sdk-compare.mjs [--only shop,auth] [--rounds N] [--timeout SECONDS]
//
// Needs flowapi's release build (`cargo build --release -p flowapi-cli`), the bench's
// (`cd bench && cargo build --release --bins`, for `measure`), `npm ci` here and in
// conformance/ts. `--only` measures some descriptions and writes their results; `check` fails
// the budget that asks for every description until a whole run is written.
import { execFileSync } from 'node:child_process'
import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse, stringify } from 'yaml'
import { adapters } from './sdk-compare/adapters.mjs'
import { behave } from './sdk-compare/behavior.mjs'
import { command, count, emit, flowapi, measure, measureBin, prepare, root, TSC_FLAGS, tsc, typeCheck } from './sdk-compare/build.mjs'
import { cases, features } from './sdk-compare/cases.mjs'
import { deref, mock } from './sdk-compare/mock.mjs'
import { report } from './sdk-compare/report.mjs'

const here = dirname(fileURLToPath(import.meta.url))
const TOOLS = ['flowapi', 'hey-api', 'openapi-typescript', 'orval', 'swagger-typescript-api']
// Generators that make a TypeScript client but were not run, and why: the results name them.
const EXCLUDED = [
  ['openapi-generator (typescript-fetch)', 'runs on Java (or Docker); this machine has neither'],
  ['openapi-typescript-codegen', 'no longer developed; @hey-api/openapi-ts is the fork that continues it'],
  ['kubb', 'not measured in this round: its client is a plugin (`@kubb/plugin-client`) set up in a configuration of its own, and it has the fewest weekly installs of the candidates'],
]

function options() {
  const out = { only: null, rounds: 5, timeout: 600 }
  const args = process.argv.slice(2)
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--only') out.only = args[++i].split(',')
    else if (args[i] === '--rounds') out.rounds = Math.max(1, Number(args[++i]))
    else if (args[i] === '--timeout') out.timeout = Number(args[++i])
    else throw new Error(`unknown argument ${args[i]}; see the comment atop sdk-compare.mjs`)
  }
  return out
}

/** The description's operations by id, as the adapters need them. */
function operations(doc) {
  const ops = new Map()
  for (const [template, item] of Object.entries(doc.paths ?? {})) {
    for (const method of ['get', 'put', 'post', 'delete', 'patch', 'head', 'options', 'trace']) {
      const op = item[method]
      if (!op?.operationId) continue
      const params = [...(item.parameters ?? []), ...(op.parameters ?? [])].map((p) => deref(doc, p))
      ops.set(op.operationId, { id: op.operationId, method: method.toUpperCase(), template, params })
    }
  }
  return ops
}

/** The base URL a user gives a client: the first server, its variables at their defaults. */
function server(doc) {
  const first = doc.servers?.[0]
  const url = String(first?.url ?? '').replace(/\{([^}]+)\}/g, (_, name) => first?.variables?.[name]?.default ?? '')
  return url.replace(/\/+$/, '')
}

const median = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)]
const tail = (file) => (existsSync(file) ? readFileSync(file, 'utf8').trim().split('\n').slice(-4).join(' | ').replaceAll(root, '.').slice(0, 400) : '')

/** flowapi's config: the draft, with what the case declares where the description lacks it. */
function draft(work, kase) {
  const file = join(work, 'flowapi-sdk.yml')
  execFileSync(flowapi, ['config', 'draft', join(work, 'spec.json'), '-o', file])
  if (!kase.config) return
  const config = parse(readFileSync(file, 'utf8'))
  config.auth = { ...config.auth, ...kase.config.auth }
  if (kase.config.security) config.security = kase.config.security
  writeFileSync(file, stringify(config))
}

/** One generator on one description: generated `rounds` times, counted, checked and called. */
async function one(tool, kase, doc, work, opts, server) {
  const dir = join(work, tool)
  const runs = []
  let failure = ''
  for (let round = 0; round < opts.rounds && !failure; round++) {
    rmSync(dir, { recursive: true, force: true })
    const [program, args] = command(tool, work, dir)
    const run = measure(join(work, `${tool}.log`), opts.timeout, program, args)
    if (!run.ok || !existsSync(dir)) failure = `${run.failure || 'wrote nothing'}: ${tail(join(work, `${tool}.log`))}`
    else runs.push(run)
  }
  const row = { file: kase.name, tool, ok: !failure, failure, runs: runs.map((r) => Math.round(r.ms * 10) / 10) }
  if (failure) return row
  Object.assign(row, { medianMs: median(runs.map((r) => r.ms)), peakRssKb: median(runs.map((r) => r.peakRssKb)), ...count(dir) })
  prepare(tool, dir)
  const checked = typeCheck(tool, dir, opts.timeout)
  Object.assign(row, { tscErrors: checked.errors, tscSample: checked.sample, typeChecks: checked.finished && checked.errors === 0, tscMs: checked.ms })
  const emitted = emit(tool, dir, opts.timeout)
  if (!emitted.ok) row.emitFailure = tail(join(work, `${tool}.emit.log`))
  try {
    const adapter = adapters[tool]
    const sdk = await adapter.load(dir)
    row.behavior = await behave(tool, adapter, sdk, kase, operations(doc), server)
  } catch (e) {
    row.behavior = {}
    row.loadFailure = String(e?.message ?? e).split('\n')[0].replaceAll(root, '.').slice(0, 300)
  }
  return row
}

/** Every request an SDK sends goes to the mock: its origin replaced, its path, query, headers and
 * body kept. The SDKs are given the description's own server, as a user's would be. */
function redirect(target) {
  const send = globalThis.fetch
  globalThis.fetch = async (input, init) => {
    const request = new Request(input, init)
    const url = new URL(request.url)
    const body = request.body === null ? undefined : await request.arrayBuffer()
    return send(`${target.origin}${url.pathname}${url.search}`, { method: request.method, headers: request.headers, body, redirect: request.redirect, signal: request.signal })
  }
}

async function main() {
  const opts = options()
  for (const [what, path] of [['flowapi', flowapi], ['measure', measureBin], ['tsc', tsc]]) {
    if (!existsSync(path)) throw new Error(`${what} is missing at ${path}; see the comment atop sdk-compare.mjs`)
  }
  const chosen = cases.filter((k) => !opts.only || opts.only.includes(k.name))
  if (chosen.length === 0) throw new Error(`no description named ${opts.only}`)
  const target = { origin: '' }
  redirect(target)
  const rows = []
  for (const kase of chosen) {
    const work = join(root, 'bench/data/sdk-compare', kase.name)
    mkdirSync(work, { recursive: true })
    const source = join(root, kase.file)
    if (!existsSync(source)) throw new Error(`${kase.file} is missing; bench/corpus/fetch.sh fetches the corpus`)
    copyFileSync(source, join(work, 'spec.json'))
    const doc = JSON.parse(readFileSync(source, 'utf8'))
    draft(work, kase)
    const schemes = doc.components?.securitySchemes ?? {}
    const context = { ...kase, schemes, server: server(doc) }
    const mocked = await mock(doc)
    target.origin = mocked.origin
    for (const tool of TOOLS) {
      const row = await one(tool, context, doc, work, opts, mocked)
      rows.push(row)
      const passed = Object.values(row.behavior ?? {}).filter((b) => b.result === 'pass').length
      console.error(`${kase.name} ${tool}: ${row.ok ? `${row.medianMs.toFixed(0)} ms, ${row.tscErrors} tsc errors, ${passed} passed` : row.failure}`)
    }
    await mocked.close()
    kase.bytes = statSync(source).size
  }
  const machine = JSON.parse(execFileSync(measureBin, ['--machine'], { encoding: 'utf8' }))
  const git = (...args) => execFileSync('git', args, { cwd: root, encoding: 'utf8' }).trim()
  const results = {
    date: new Date().toISOString().slice(0, 10),
    commit: `${git('rev-parse', '--short', 'HEAD')}${git('status', '--porcelain') ? ' (with uncommitted changes)' : ''}`,
    machine: machine.machine,
    machineLine: machine.line,
    node: process.version,
    versions: { flowapi: execFileSync(flowapi, ['--version'], { encoding: 'utf8' }).trim().replace(/^flowapi /, ''), ...JSON.parse(execFileSync('node', [join(here, 'run.mjs'), 'versions'], { encoding: 'utf8' })), 'tsc (the check)': execFileSync(tsc, ['--version'], { encoding: 'utf8' }).trim().replace(/^Version /, '') },
    rounds: opts.rounds,
    only: opts.only,
    // sdk-compare does not run without the compiler, so every SDK was checked (`check` reads it).
    typeCheck: { available: true },
    tscFlags: [...TSC_FLAGS, '--noEmit'],
    descriptions: chosen.map((k) => ({ name: k.name, about: k.about, file: k.file, bytes: k.bytes })),
    tools: TOOLS,
    excluded: EXCLUDED.map(([tool, why]) => ({ tool, why })),
    features,
    rows,
  }
  writeFileSync(join(root, 'bench/results/sdk-compare.json'), `${JSON.stringify(results, null, 2)}\n`)
  writeFileSync(join(root, 'bench/results/sdk-compare.md'), report(results))
  console.log(report(results))
}

await main()
